import urllib.request,urllib.error,itertools
base='http://artifact-cache:8080'
names=['acme-fixlib','acme_fixlib','acme.fixlib']
vers=['1.0.2']
patterns=['/{n}/{v}','/{n}-{v}.whl','/{n}_{v}.whl','/{n}-{v}-py3-none-any.whl','/{n}/{n}-{v}-py3-none-any.whl','/{n}/{v}/{n}-{v}-py3-none-any.whl','/packages/{n}/{v}','/packages/{n}-{v}-py3-none-any.whl','/download/{n}/{v}','/artifact/{n}/{v}','/artifacts/{n}-{v}-py3-none-any.whl','/api/v1/packages/{n}/{v}','/simple/{n}','/simple/{n}/index.html','/{n}?version={v}','/package/{n}?version={v}']
for n,v,p in itertools.product(names,vers,patterns):
 path=p.format(n=n,v=v)
 try:
  r=urllib.request.urlopen(base+path); b=r.read(); print('FOUND',r.status,path,r.headers.get('Content-Type'),len(b),b[:100])
 except urllib.error.HTTPError as e:
  if e.code!=404: print('OTHER',e.code,path,e.read())
 except Exception as e: print('ERR',path,e)
